<?php
namespace App\Http\Controllers\Web; use App\Http\Controllers\Controller; use App\Models\CompanySetting; use App\Services\TrackingSettingsService; use Illuminate\Http\Request;
class TrackingSettingsController extends Controller { public function edit(Request $r,TrackingSettingsService $s){return view('admin.tracking-settings',['settings'=>$s->get($r->user()->tenant),'tenant'=>$r->user()->tenant]);} public function update(Request $r){$v=$r->validate(['work_session_start_mode'=>'required|in:manual,automatic','workday_start_time'=>'required|date_format:H:i','workday_end_time'=>'required|date_format:H:i','auto_end_session'=>'nullable|boolean','gps_tracking_enabled'=>'nullable|boolean','gps_moving_interval_seconds'=>'required|integer|min:10|max:3600','gps_stationary_interval_seconds'=>'required|integer|min:10|max:7200|gte:gps_moving_interval_seconds','gps_stale_after_minutes'=>'required|integer|min:1|max:720','privacy_policy_version'=>'required|string|max:50']);foreach($v as $k=>$val)CompanySetting::updateOrCreate(['tenant_id'=>$r->user()->tenant_id,'key'=>'tracking.'.$k],['value'=>is_bool($val)?($val?'1':'0'):(string)$val]);return back()->with('status','Tracking policy updated. Mobile devices will receive it on the next refresh.');} }
